<?php
require __DIR__.'/config.php';require_login();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$items=$_POST['items']??[];$customer=(int)($_POST['customer_id']??0)?:null;$method=$_POST['payment_method']??'cash';$allowed=['cash','utang','gcash','bank'];if(!in_array($method,$allowed,true))throw new RuntimeException('Invalid payment method.');if($method==='utang'&&!$customer)throw new RuntimeException('Choose a customer for an utang sale.');if($method==='utang'&&$customer){$checkCustomer=$pdo->prepare('SELECT id FROM customers WHERE id=?');$checkCustomer->execute([$customer]);if(!$checkCustomer->fetch())throw new RuntimeException('Selected customer was not found. Please select a valid customer.');}if(!is_array($items)||!$items)throw new RuntimeException('Add at least one item.');$pdo->beginTransaction();$clean=[];$subtotal=0;foreach($items as $id=>$qty){$id=(int)$id;$qty=(int)$qty;if($qty<1)continue;$st=$pdo->prepare('SELECT * FROM products WHERE id=? AND active=1 FOR UPDATE');$st->execute([$id]);$p=$st->fetch();if(!$p)throw new RuntimeException('A selected product is no longer available.');if($p['stock']<$qty)throw new RuntimeException('Not enough stock for '.$p['name'].'. Available: '.$p['stock']);$line=$p['price']*$qty;$subtotal+=$line;$clean[]=['p'=>$p,'qty'=>$qty,'line'=>$line];}if(!$clean)throw new RuntimeException('Add valid item quantities.');$discount=max(0,(float)($_POST['discount']??0));if($discount>$subtotal)throw new RuntimeException('Discount cannot exceed subtotal.');$total=round($subtotal-$discount,2);$paid=$method==='utang'?0:max(0,(float)($_POST['amount_paid']??0));if($method!=='utang'&&$paid<$total)throw new RuntimeException('Amount paid is less than the total.');$status=$method==='utang'?'utang':'paid';$receipt='JB-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$st=$pdo->prepare('INSERT INTO sales(receipt_no,customer_id,user_id,subtotal,discount,total,amount_paid,change_due,payment_method,status) VALUES(?,?,?,?,?,?,?,?,?,?)');$st->execute([$receipt,$customer,current_user()['id'],$subtotal,$discount,$total,$paid,$method==='utang'?0:$paid-$total,$method,$status]);$saleId=(int)$pdo->lastInsertId();foreach($clean as $it){$p=$it['p'];$qty=$it['qty'];$pdo->prepare('INSERT INTO sale_items(sale_id,product_id,product_name,quantity,unit_price,unit_cost,line_total) VALUES(?,?,?,?,?,?,?)')->execute([$saleId,$p['id'],$p['name'],$qty,$p['price'],$p['cost'],$it['line']]);$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?')->execute([$qty,$p['id']]);$pdo->prepare('INSERT INTO inventory_logs(product_id,user_id,change_qty,reason) VALUES(?,?,?,?)')->execute([$p['id'],current_user()['id'],-$qty,'Sale '.$receipt]);}if($method==='utang')$pdo->prepare('INSERT INTO debt_payments(sale_id,amount,user_id,notes) VALUES(?,0,?,?)')->execute([$saleId,current_user()['id'],'Utang sale opened']);$pdo->commit();flash('Sale completed. Receipt: '.$receipt);redirect('receipt.php?id='.$saleId);}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();flash($ex->getMessage(),'error');redirect('pos.php');}}
$products=$pdo->query('SELECT id,name,sku,price,stock FROM products WHERE active=1 AND stock>0 ORDER BY name')->fetchAll();$customers=$pdo->query('SELECT id,name,phone FROM customers ORDER BY name')->fetchAll();$pageTitle='POS Register';require __DIR__.'/partials/header.php';?>
<div class="page-intro"><div><h1>POS Register</h1><p>Select products, review the cart, and complete a sale.</p></div><span class="pill paid">● Ready to sell</span></div><form method="post" id="pos-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="pos-layout"><section class="panel"><div class="panel-heading"><div><h2>Available products</h2><p>Click Add to place an item in the cart.</p></div><input id="product-search" class="search-input" placeholder="Search products..."></div><div class="product-grid" id="product-grid"><?php foreach($products as $p):?><article class="product-tile" data-name="<?=e(strtolower($p['name'].' '.$p['sku']))?>"><span class="tile-icon">▤</span><b><?=e($p['name'])?></b><small><?=e($p['sku']?:'No SKU')?> · <?=$p['stock']?> in stock</small><strong><?=money($p['price'])?></strong><button type="button" class="btn secondary add-product" data-id="<?=$p['id']?>" data-name="<?=e($p['name'])?>" data-price="<?=$p['price']?>" data-stock="<?=$p['stock']?>">＋ Add</button></article><?php endforeach;?></div><?php if(!$products):?><p class="empty">No products with stock are available. Add products in Inventory first.</p><?php endif;?></section><aside class="panel cart-panel"><div class="panel-heading"><div><h2>Current sale</h2><p>Review items before checkout.</p></div><span id="cart-count" class="count-badge">0</span></div><div id="cart-items" class="cart-items"><p class="empty">Your cart is empty.</p></div><div class="cart-summary"><div><span>Subtotal</span><b id="subtotal">₱0.00</b></div><div class="field"><label>Discount (₱)</label><input type="number" id="discount" name="discount" min="0" step=".01" value="0"></div><div class="total-line"><span>Total</span><strong id="total">₱0.00</strong></div><label>Customer (required for utang)</label><select name="customer_id" id="customer-id"><option value="">Walk-in customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?><?= $c['phone']?' · '.e($c['phone']):''?></option><?php endforeach;?></select><label>Payment method</label><select name="payment_method" id="payment-method"><option value="cash">Cash</option><option value="gcash">GCash</option><option value="bank">Bank transfer</option><option value="utang">Utang / pay later</option></select><div id="paid-wrap"><label>Amount received (₱)</label><input type="number" id="amount-paid" name="amount_paid" min="0" step=".01" value="0"></div><div class="change-box">Change: <b id="change">₱0.00</b></div><button class="btn primary full checkout-btn">Complete sale</button></div></aside></div></form>
<script>window.JOBILI_PRODUCTS = <?=json_encode(array_map(fn($p)=>['id'=>(int)$p['id'],'name'=>$p['name'],'price'=>(float)$p['price'],'stock'=>(int)$p['stock']],$products),JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>;</script>
